 if($action==='database'){$db=gszDatabaseFields($_POST);$ignore=!empty($_POST['ignore_legacy']);try{gszLoadConfig();}catch(Throwable $e){if(!$ignore)throw new RuntimeException('Bisherige Konfiguration ist fehlerhaft. Zuerst Diagnose prüfen und das bewusste Übergehen bestätigen.');}$db['managed_ignore_legacy']=$ignore;$pdo=gszConnectDatabase($db);require_once dirname(__DIR__).'/private/setup_schema.php';$inspection=gszSetupInspect($pdo);gszSetupCandidateSave($db);$_SESSION['setup_notice']='Verbindung bestätigt. Bestehende Tabellen: '.$inspection['tables'].'. Noch keine Migration und noch keine aktive Konfiguration geändert.';}
 elseif($action==='owner'){$pdo=gszConnectDatabase(gszSetupCandidate());gszSetupOwner($pdo,trim((string)($_POST['owner_email']??'')),(string)($_POST['owner_password']??''));$_SESSION['setup_notice']='Bestehende Inhaberanmeldung bestätigt.';}
 elseif($action==='migrate'){$db=gszSetupCandidate();$pdo=gszConnectDatabase($db);require_once dirname(__DIR__).'/private/setup_schema.php';$before=gszSetupInspect($pdo);if(!$before['can_migrate'])throw new RuntimeException('GSZ_SCHEMA_BLOCKED');if($before['status']!=='empty')gszSetupRequireOwner($pdo);foreach(['confirm_migration','confirm_backup','confirm_restore','confirm_exclusive'] as $key)if(empty($_POST[$key]))throw new RuntimeException('Migration, gemeinsame Datei-/DB-Sicherung, Restoreprüfung und exklusives Testfenster ausdrücklich bestätigen.');if($before['status']!=='empty'&&!preg_match('/^[a-f0-9]{64}$/D',(string)($_POST['backup_sha256']??'')))throw new RuntimeException('SHA256 der überprüften Datenbanksicherung erforderlich.');require_once dirname(__DIR__).'/private/release_integrity.php';if(gszReleaseIntegrity()['status']!=='PASS')throw new RuntimeException('Paket unvollständig. Vollständiges zusammengehöriges ZIP erneut übertragen, keine Migration gestartet.');$after=gszSetupMigrate($pdo);$legacy=dirname(__DIR__).'/private/config.php';if(file_exists($legacy)){if(!gszConfigSecurity($legacy)['safe_location']||!@chmod($legacy,0600))throw new RuntimeException('GSZ_PRIVATE_PERMISSIONS');}gszManagedSave($db);$_SESSION['setup_migrated']=true;$_SESSION['setup_notice']='Schema '.$after['version'].' bestätigt. Verbindung sicher gespeichert; keine alten Inhaber ersetzt.';}
 elseif($action==='admin'){gszSetupRequireActive();$pdo=gszConnectDatabase(gszSetupCandidate());if(empty($_SESSION['setup_migrated']))throw new RuntimeException('Schema zuerst einrichten.');gszSetupCreateAdmin($pdo,trim((string)($_POST['admin_email']??'')),(string)($_POST['admin_password']??''),(string)($_POST['admin_repeat']??''));$_SESSION['setup_notice']='Individueller Inhaber angelegt. Kein Standardpasswort verwendet.';}
 elseif($action==='mail'){gszSetupRequireActive();$pdo=gszConnectDatabase(gszSetupCandidate());gszSetupRequireOwner($pdo);if(empty($_SESSION['setup_migrated']))throw new RuntimeException('Schema zuerst einrichten.');require_once dirname(__DIR__).'/private/setup_mail.php';$config=gszLoadConfig();$values=gszSetupMailSave($_POST,$config);$_SESSION['setup_notice']='Postfachkonfiguration sicher gespeichert. Versand bleibt bis zur gesonderten bewussten Freigabe gesperrt.';}
 elseif($action==='mail_probe'){gszSetupRequireActive();$pdo=gszConnectDatabase(gszSetupCandidate());gszSetupRequireOwner($pdo);require_once dirname(__DIR__).'/private/setup_mail.php';$_SESSION['setup_mail_probe']=gszSetupMailProbe(gszLoadConfig());}
 elseif($action==='https_probe'){require_once dirname(__DIR__).'/private/waste_provider.php';try{$rows=json_decode(wasteFetchRemote(GszRegioWasteProvider::BASE.'/orte',GszRegioWasteProvider::HOST,'json'),true,32,JSON_THROW_ON_ERROR);$_SESSION['setup_https_probe']=['status'=>'PASS','at'=>gmdate('c'),'message'=>'Nativer PHP-HTTPS-Abruf zum offiziellen Kalenderhost bestätigt, '.count($rows).' Kommuneneinträge.'];}catch(Throwable $e){$_SESSION['setup_https_probe']=['status'=>'BLOCKED','at'=>gmdate('c'),'message'=>'Direkter PHP-TLS-Abruf nicht bestätigt. Hosting-DNS, ausgehendes HTTPS und CA-Vertrauensspeicher prüfen; kein Zertifikatschutz deaktiviert.'];}}
 elseif($action==='finish'){$pdo=gszConnectDatabase(gszSetupCandidate());if(empty($_POST['confirm_finish']))throw new RuntimeException('Einrichtung abschließen ausdrücklich bestätigen.');gszSetupFinish($pdo);header('Location: index.php',true,303);exit;}
 else throw new RuntimeException('Unbekannter Einrichtungsschritt.');}
 }catch(Throwable $e){$msg=$e->getMessage();$_SESSION['setup_error']=str_starts_with($msg,'GSZ_SCHEMA_')?'Schemaschutz: '.$msg.'. Vorhandene Struktur/Ledger nicht automatisch reparieren; vollständige Sicherung/Restore prüfen.':(($e instanceof PDOException||$e instanceof ParseError||str_starts_with($msg,'GSZ_'))?gszSafeError($e)['message'].' ['.gszSafeError($e)['code'].']':$msg);}
 flock($actionLock,LOCK_UN);fclose($actionLock);header('Location: setup.php',true,303);exit;
