 try{$pdo=gszConnectDatabase(gszSetupCandidate());require_once dirname(__DIR__).'/private/setup_schema.php';$inspection=gszSetupInspect($pdo);if($inspection['version']!==null&&(int)$inspection['version']>=192)$admins=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();}catch(Throwable $e){}
}
