<?php if($inspection['can_migrate']):?><form method="post"><?php sf('migrate');?><label><input type="checkbox" name="confirm_backup" value="1" required> Bestehende Dateien und Datenbank gemeinsam gesichert (bei leerer Neuinstallation keine Altbestände).</label><label><input type="checkbox" name="confirm_restore" value="1" required> Sicherung auf separater Testumgebung wiederhergestellt und geprüft bzw. leere neue Datenbank bestätigt.</label><label>SHA-256 der geprüften Datenbanksicherung (bei Bestand erforderlich)<input name="backup_sha256" minlength="64" maxlength="64"></label><label><input type="checkbox" name="confirm_exclusive" value="1" required> Ausschließlich freigegebene Testdatenbank; exklusives Wartungsfenster bestätigt.</label><label><input type="checkbox" name="confirm_migration" value="1" required> Angezeigte additive Migration bzw. Übernahme ausdrücklich freigeben. Keine vorhandene Datenbank löschen/ersetzen.</label><button>Schema sicher übernehmen / aktualisieren</button></form><?php endif?></section><?php endif?>
